using System;using System.Xml.Linq;class Check{static void Main(){var a=new Inventory();var root=new Device("5690");a.Devices.Add(root);foreach(string id in new[]{"1","2","16"})Reader.ImportDect(a,root,XElement.Parse("<row><NewID>"+id+"</NewID><NewActive>"+(id=="1"?"1":"0")+"</NewActive></row>"));if(a.Devices.Count!=3||a.Links.Count!=1||!a.Devices[2].Inactive||!root.Details.Contains("16"))throw new Exception();var s=Reader.Thermostat(XElement.Parse("<device><present>1</present><battery>65</battery><hkr><tist>41</tist><tsoll>253</tsoll></hkr></device>"));if(!s.Contains("20,5 °C")||!s.Contains("Soll Aus")||!s.Contains("65 %")||!Reader.Thermostat(XElement.Parse("<device><hkr/></device>")).Contains("Ist unbekannt"))throw new Exception(s);Console.WriteLine("OK");}}